-- Instrument 9: Business Performance Monitoring & Executive Dashboard
UPDATE assessment_template_versions tv
SET schema_definition=$schema${"instrument_number":9,"template_name":"Business Performance Monitoring & Executive Dashboard","description":"An advisor-led monitoring framework and executive dashboard that tracks a focused set of business KPIs, compares current performance with defined baselines and targets, records variance explanations and supports management decisions and benefits realization.","schema_status":"active","sections":[{"id":"monitoring_framework","title":"1. Monitoring framework & executive objectives","description":"Define how performance will be measured, reviewed and acted upon.","questions":[{"key":"mon_objectives","label":"Business objectives and value drivers monitored","type":"textarea","required":true},{"key":"mon_cadence","label":"Executive review cadence and reporting calendar","type":"select","required":true,"options":["Weekly operating review + monthly executive review","Monthly executive review","Quarterly strategic review","Other / defined below"]},{"key":"mon_cadence_other","label":"Other cadence / reporting schedule","type":"text","required":false},{"key":"mon_audience","label":"Dashboard audience and decision-makers","type":"textarea","required":true},{"key":"mon_owners","label":"Data owners, KPI owners and decision rights","type":"textarea","required":true},{"key":"mon_definitions","label":"Metric definitions, source-of-truth rules and change control","type":"textarea","required":true},{"key":"mon_thresholds","label":"Escalation thresholds and alert rules","type":"textarea","required":true},{"key":"mon_data_quality","label":"Data quality, completeness and verification standards","type":"textarea","required":true}]},{"id":"metric_1","title":"1. KPI / performance measure 1","description":"Define a measurable indicator with a consistent unit, scope, period and source. Leave unknown values blank rather than entering zero.","questions":[{"key":"k1_name","label":"KPI / measure name","type":"text","required":true},{"key":"k1_dimension","lab