tems","Scalability & Business Value"]},{"key":"k5_objective","label":"Strategic objective supported","type":"text","required":false},{"key":"k5_definition","label":"Metric definition, scope and calculation","type":"textarea","required":false},{"key":"k5_unit","label":"Unit of measure","type":"text","required":false},{"key":"k5_direction","label":"Desired direction","type":"select","required":false,"options":["Higher is better","Lower is better","Within defined range","Qualitative / manually assessed"]},{"key":"k5_baseline","label":"Baseline value","type":"number","required":false},{"key":"k5_baseline_date","label":"Baseline period / date","type":"text","required":false},{"key":"k5_target","label":"Target value","type":"number","required":false},{"key":"k5_current","label":"Latest actual value","type":"number","required":false},{"key":"k5_current_date","label":"Latest measurement date / period","type":"text","required":false},{"key":"k5_frequency","label":"Measurement frequency","type":"select","required":false,"options":["Weekly","Monthly","Quarterly","Per transaction / event","Other / defined below"]},{"key":"k5_owner","label":"Data owner / accountable KPI owner","type":"text","required":false},{"key":"k5_source","label":"System, report or evidence source","type":"text","required":false},{"key":"k5_status_notes","label":"Variance explanation, data quality and context","type":"textarea","required":false}]},{"id":"metric_6","title":"6. KPI / performance measure 6","description":"Define a measurable indicator with a consistent unit, scope, period and source. Leave unknown values blank rather than entering zero.","questions":[{"key":"k6_name","label":"KPI / measure name","type":"text","required":false},{"key":"k6_dimension","label":"Performance dimension","type":"select","required":false,"options":["Financial Performance","Operational Effectiveness","Organizational Effectiveness","Commercial Performance","Technology & Systems","Scalability & Business Value"]},{"key":"k6_objective","label":"Strategic objective supported","type":"text","required":false},{"key":"k6_definition","label":"Metric definition, scope and calculation","type":"textarea","required":false},{"key":"k6_unit","label":"Unit of measure","type":"text","required":false},{"key":"k6_direction","label":"Desired direction","type":"select","required":false,"options":["Higher is better","Lower is better","Within defined range","Qualitative / manually assessed"]},{"key":"k6_baseline","label":"Baseline value","type":"number","required":false},{"key":"k6_baseline_date","label":"Baseline period / date","type":"text","required":false},{"key":"k6_target","label":"Target value","type":"number","required":false},{"key":"k6_current","label":"Latest actual value","type":"number","required":false},{"key":"k6_current_date","label":"Latest measurement date / period","type":"text","required":false},{"key":"k6_frequency","label":"Measurement frequency","type":"select","required":false,"options":["Weekly","Monthly","Quarterly","Per transaction / event","Other / defined below"]},{"key":"k6_owner","label":"Data owner / accountable KPI owner","type":"text","required":false},{"key":"k6_source","label":"System, report or evidence source","type":"text","required":false},{"key":"k6_status_notes","label":"Variance explanation, data quality and context","type":"textarea","required":false}]},{"id":"executive_review","title":"8. Executive performance review & management response","description":"Record the interpretation, decisions and actions arising from the current review period.","questions":[{"key":"mon_period","label":"Executive review period / as-of date","type":"text","required":true},{"key":"mon_summary","label":"Executive performance summary","type":"textarea","required":true},{"key":"mon_wins","label":"Performance gains and validated benefits realized","type":"textarea","required":false},{"key":"mon_gaps","label":"Material variances, underperformance and emerging risks","type":"textarea","required":true},{"key":"mon_causes","label":"Evidence-supported explanations and unresolved hypotheses","type":"textarea","required":false},{"key":"mon_actions","label":"Corrective actions, owners and due dates","type":"textarea","required":true},{"key":"mon_decisions","label":"Decisions, escalations and resources required","type":"textarea","required":true},{"key":"mon_forecast","label":"Forward outlook, assumptions and confidence","type":"textarea","required":false},{"key":"mon_customer_employee","label":"Customer, employee and operational impacts","type":"textarea","required":false},{"key":"mon_next_review","label":"Next review date and required evidence","type":"text","required":true},{"key":"mon_advisor_confidence","label":"Advisor confidence in dashboard completeness and interpretation","type":"select","required":true,"options":["High — reliable measures and corroborated sources","Moderate — useful view with known data gaps","Low — preliminary measures; validate before decisions","Insufficient — do not rely on this dashboard yet"]}]}],"assessment_policy":"Every KPI requires a stable definition, unit, scope, period, owner and source. Missing data is unknown, never zero. Compare values only when definitions and periods are consistent. Automated status labels are simple threshold comparisons, not causal diagnoses. Separate actual results, approved targets, forecasts and hypotheses. Benefits must be validated against a baseline and attributable assumptions; avoid double counting. Management owns corrective action and operating decisions."}$schema$::jsonb,
 scoring_definition=$score${"rating_owner":"advisor","missing_data_policy":"Unknown and unmeasured values remain blank; never coerce to zero.","metric_policy":"KPIs require consistent definitions, units, scope, periods, owners and sources.","status_policy":"Automated status labels compare current actuals to target only when both values and direction are present. They do not explain causes or forecast outcomes.","benefits_policy":"Validate realized benefits against a documented baseline; separate actuals, targets, forecasts and hypotheses."}$score$::jsonb,
 published_at=COALESCE(tv.published_at,now())
FROM assessment_templates t
WHERE tv.template_id=t.id AND t.instrument_number=9 AND tv.version_number=t.current_version;
